12	    const id = ++this.#id;
13	    this.#timers.set(id, { at: this.#now + ms, fn, id });
14	    return id;
15	  }
16	
17	  clearTimeout(id) {
18	    this.#timers.delete(id);
19	  }
20	
21	  get pending() {
22	    return this.#timers.size;
23	  }
