{"path": "src/pqueue.js", "content": "/**
 * Stable priority queue. Higher `priority` comes out first; entries with equal priority come out in the
 * order of their `seq` (lower first). `seq` is chosen by the caller, so an entry that is pushed again later
 * with its old `seq` goes back in front of entries that were queued after it.
 *
 *   push(item, priority, seq)       add an entry
 *   takeFirst(accept)               remove and return the first item (in queue order) for which
 *                                   accept(item) is true, or undefined when there is none
 *   remove(item)                    remove that item; returns true when it was queued
 *   size                            number of queued entries
 */
export class PriorityQueue {
  #entries = [];

  #compare(a, b) {
    return b.priority - a.priority || a.seq - b.seq;
  }

  push(item, priority, seq) {
    const entry = { item, priority, seq };
    let i = this.#entries.length;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.#compare(this.#entries[parent], entry) <= 0) break;
      this.#entries[i] = this.#entries[parent];
      i = parent;
    }
    this.#entries[i] = entry;
  }

  takeFirst(accept) {
    const entries = this.#entries;
    for (let i = 0; i < entries.length; i++) {
      if (!accept(entries[i].item)) continue;
      const last = entries.pop();
      if (i < entries.length) {
        entries[i] = last;
        // Sift down.
        let n = entries.length;
        for (;;) {
          const l = 2 * i + 1;
          if (l >= n) break;
          let r = l + 1;
          let m = l;
          if (r < n && this.#compare(entries[l], entries[r]) > 0) m = r;
          if (this.#compare(entries[i], entries[m]) <= 0) break;
          [entries[i], entries[m]] = [entries[m], entries[i]];
          i = m;
        }
      }
      return entries.length === i ? last : entries[i].item;
    }
    return undefined;
  }

  remove(item) {
    const entries = this.#entries;
    const i = entries.findIndex((e) => e.item === item);
    if (i < 0) return false;
    const last = entries.pop();
    if (i < entries.length) {
      entries[i] = last;
      // Sift down.
      let n = entries.length;
      for (;;) {
        const l = 2 * i + 1;
        if (l >= n) break;
        let r = l + 1;
        let m = l;
        if (r < n && this.#compare(entries[l], entries[r]) > 0) m = r;
        if (this.#compare(entries[i], entries[m]) <= 0) break;
        [entries[i], entries[m]] = [entries[m], entries[i]];
        i = m;
      }
    }
    return true;
  }

  get size() {
    return this.#entries.length;
  }
}
