{"path": "src/scheduler.js", "content": "import { CancelledError } from './errors.js';
import { delayFor } from './backoff.js';
import { deferred } from './deferred.js';
import { normalizeJobOptions, normalizeOptions } from './options.js';
import { PriorityQueue } from './pqueue.js';

/**
 * Async job scheduler. All timing goes through the injected `clock` ({ setTimeout(fn, ms) -> handle,
 * clearTimeout(handle) }); nothing here may use real timers.
 *
 *   const s = new Scheduler({ concurrency: 2, clock });
 *   const result = await s.schedule(async ({ attempt, signal }) => value, options);
 *
 * Job options (see normalizeJobOptions): key, priority, retries, backoff, signal, shouldRetry.
 *
 * Contract:
 *  1. At most `concurrency` job functions are running at once.
 *  2. Queue order is higher `priority` first, then first scheduled first (arrival order).
 *  3. `schedule` returns (invalid options throw a TypeError synchronously) a promise for the job function's result. When a slot is free the
 *     job function is called synchronously, inside `schedule`. Otherwise it is called synchronously from the
 *     moment a slot frees up (the settlement of a running job, a cancellation, or an expiring backoff timer).
 *  4. Jobs sharing a `key` never run at the same time. A queued job whose key is busy is skipped, not waited
 *     for: later jobs with free keys start before it. Jobs without a key never conflict.
 *  5. The job function receives { attempt, signal }; attempt is 1 for the first call. It may throw
 *     synchronously or return a rejected promise; both count as a failed attempt.
 *  6. `retries` is the number of retries after the first attempt (at most retries + 1 attempts). A failed
 *     attempt is retried while retries remain and shouldRetry(error, attempt) is true; otherwise the promise rejects with the last error. CancelledError is never retried.
 *  7. Before a retry the job waits delayFor(attempt, backoff) ms on the clock. While it waits it does not
 *     use a concurrency slot, but it keeps its key reserved (no other job with that key starts).
 *     When the wait ends the job re-enters the queue with its original priority and arrival order.
 *  8. If `signal` is already aborted when `schedule` is called, the promise rejects with CancelledError and
 *     the job function is never called.
 *  9. Aborting a queued job removes it from the queue and rejects with CancelledError.
 * 10. Aborting a job that is waiting for a retry cancels the timer, releases its key and rejects with CancelledError.
 * 11. Aborting a running job rejects its promise with CancelledError immediately and aborts the `signal`
 *     passed to the job function. The function may still be running: its slot and key stay occupied until it
 *     settles, and its result or error is then ignored (no retry).
 * 12. `idle()` returns a promise that resolves when no job is queued, running or waiting for a retry
 *     (immediately when that already holds). `stats()` returns { queued, running, waiting }, where
 *     `running` counts occupied slots (including aborted jobs whose function has not settled yet).
 */
export class Scheduler {
  #opts;
  #queue = new PriorityQueue();
  #running = 0;
  #waiting = 0;
  #busyKeys = new Set();
  #seq = 0;
  #idleWaiters = [];

  constructor(opts) {
    this.#opts = normalizeOptions(opts);
  }

  schedule(fn, options) {
    const opts = normalizeJobOptions(options);
    const { clock } = this.#opts;
    const job = {
      fn,
      key: opts.key,
      priority: opts.priority,
      retries: opts.retries,
      backoff: opts.backoff,
      shouldRetry: opts.shouldRetry,
      signal: opts.signal,
      attempt: 0,
      seq: ++this.#seq,
      state: 'queued',
      timer: null,
      deferred: deferred(),
    };
    if (job.signal?.aborted) {
      job.state = 'done';
      job.deferred.reject(new CancelledError());
      return job.deferred.promise;
    }
    if (job.signal) {
      job.signal.addEventListener('abort', () => this.#abort(job), { once: true });
    }
    this.#queue.push(job, job.priority, job.seq);
    this.#pump();
    return job.deferred.promise;
  }

  #abort(job) {
    if (job.state === 'queued') {
      this.#queue.remove(job);
      job.state = 'done';
      job.deferred.reject(new CancelledError());
      this.#pump();
    } else if (job.state === 'waiting') {
      if (job.timer !== null) {
        this.#opts.clock.clearTimeout(job.timer);
        job.timer = null;
      }
      this.#waiting--;
      if (job.key !== undefined) this.#busyKeys.delete(job.key);
      job.state = 'done';
      job.deferred.reject(new CancelledError());
      this.#pump();
    } else if (job.state === 'running') {
      job.aborted = true;
      job.deferred.reject(new CancelledError());
    }
  }

  #pump() {
    for (;;) {
      if (this.#running >= this.#opts.concurrency) break;
      const job = this.#queue.takeFirst((j) => j.key === undefined || !this.#busyKeys.has(j.key));
      if (!job) break;
      this.#start(job);
    }
    if (this.#queue.size === 0 && this.#running === 0 && this.#waiting === 0) {
      const waiters = this.#idleWaiters;
      this.#idleWaiters = [];
      for (const resolve of waiters) resolve();
    }
  }

  #start(job) {
    job.state = 'running';
    job.attempt++;
    this.#running++;
    if (job.key !== undefined) this.#busyKeys.add(job.key);
    const ctx = { attempt: job.attempt, signal: job.signal };
    let result;
    try {
      result = job.fn(ctx);
    } catch (error) {
      result = Promise.reject(error);
    }
    Promise.resolve(result).then(
      (value) => {
        if (job.state !== 'running') return;
        this.#running--;
        if (job.key !== undefined) this.#busyKeys.delete(job.key);
        job.state = 'done';
        job.deferred.resolve(value);
        this.#pump();
      },
      (error) => {
        if (job.state !== 'running') return;
        this.#running--;
        if (job.key !== undefined) this.#busyKeys.delete(job.key);
        if (error instanceof CancelledError || job.attempt > job.retries || !job.shouldRetry(error, job.attempt)) {
          job.state = 'done';
          job.deferred.reject(error);
          this.#pump();
          return;
        }
        job.state = 'waiting';
        this.#waiting++;
        if (job.key !== undefined) this.#busyKeys.add(job.key);
        job.timer = this.#opts.clock.setTimeout(() => {
          job.timer = null;
          this.#waiting--;
          this.#queue.push(job, job.priority, job.seq);
          this.#pump();
        }, delayFor(job.attempt, job.backoff));
        this.#pump();
      },
    );
  }

  idle() {
    if (this.#queue.size === 0 && this.#running === 0 && this.#waiting === 0) return Promise.resolve();
    return new Promise((resolve) => this.#idleWaiters.push(resolve));
  }

  stats() {
    return { queued: this.#queue.size, running: this.#running, waiting: this.#waiting };
  }
}
"}
